const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');
function make(vals, o = {}) {
  const s = { opens: 0, closes: 0, reads: 0 };
  const src = { open: async () => { s.opens++; return {
    read: async () => { s.reads++; if (o.readErr && s.reads === o.readErr) throw new Error('read'); return vals.length ? vals.shift() : null; },
    close: async () => { s.closes++; if (o.closeErr) throw new Error('close'); } }; } };
  return [src, s];
}
async function main() {
  // unopened generator: return does nothing
  let [src, s] = make(['a']);
  await new EventService(src).stream().return();
  assert.deepEqual(s, { opens: 0, closes: 0, reads: 0 });
  // lazy, no read-ahead, break closes once
  [src, s] = make(['a', 'b', 'c']);
  const g = new EventService(src).stream();
  assert.equal(s.opens, 0);
  assert.deepEqual(await g.next(), { value: 'A', done: false });
  assert.deepEqual([s.opens, s.reads, s.closes], [1, 1, 0]);
  await g.return(); await g.return();
  assert.deepEqual([s.reads, s.closes], [1, 1]);
  // exhaustion
  [src, s] = make(['a']);
  for await (const _ of new EventService(src).stream());
  assert.deepEqual([s.reads, s.closes], [2, 1]);
  // read failure, with close failure too
  [src, s] = make(['a'], { readErr: 1, closeErr: true });
  await assert.rejects(async () => { for await (const _ of new EventService(src).stream()); }, /read/);
  assert.equal(s.closes, 1);
  // mapper failure
  [src, s] = make(['a'], { closeErr: true });
  await assert.rejects(async () => { for await (const _ of new EventService(src, () => { throw new Error('map'); }).stream()); }, /map/);
  assert.equal(s.closes, 1);
  // injected throw
  [src, s] = make(['a', 'b'], { closeErr: true });
  const g2 = new EventService(src).stream(); await g2.next();
  await assert.rejects(g2.throw(new Error('inj')), /inj/);
  assert.equal(s.closes, 1);
  // close failure propagates otherwise
  [src, s] = make(['a'], { closeErr: true });
  await assert.rejects(async () => { for await (const _ of new EventService(src).stream()); }, /close/);
  [src, s] = make(['a', 'b'], { closeErr: true });
  const g3 = new EventService(src).stream(); await g3.next();
  await assert.rejects(g3.return(), /close/);
  assert.equal(s.closes, 1);
}
module.exports = main();
